import Foundation
import Crypto

// Secure message framing protocol for inter-service communication
// Used behind mTLS-authenticated service mesh

struct FrameHeader {
    let version: UInt8
    let flags: UInt8
    let payloadType: UInt16
    let payloadLength: UInt16
    let extensionLength: Int16  // Signed: negative means "use default extensions"
    let checksum: UInt32
}

class SecureFrameProcessor {
    private let symmetricKey: SymmetricKey
    private let maxFrameSize: Int = 65536
    private var frameBuffer: Data
    private var processedFrames: Int = 0

    init(keyMaterial: Data) {
        // Derive key using HKDF - proper key derivation
        self.symmetricKey = SymmetricKey(data: HKDF<SHA256>.deriveKey(
            inputKeyMaterial: SymmetricKey(data: keyMaterial),
            salt: "frame-processor-v2".data(using: .utf8)!,
            info: "aes-gcm-256".data(using: .utf8)!,
            outputByteCount: 32
        ))
        self.frameBuffer = Data(capacity: maxFrameSize)
    }

    /// Parse and validate frame header from raw bytes
    func parseHeader(from data: Data) -> FrameHeader? {
        guard data.count >= 12 else { return nil }

        let version = data[data.startIndex]
        guard version == 2 else { return nil }  // Only support v2

        let flags = data[data.startIndex + 1]
        let payloadType = data.subdata(in: (data.startIndex+2)..<(data.startIndex+4))
            .withUnsafeBytes { $0.load(as: UInt16.self) }.bigEndian
        let payloadLength = data.subdata(in: (data.startIndex+4)..<(data.startIndex+6))
            .withUnsafeBytes { $0.load(as: UInt16.self) }.bigEndian
        let extensionLength = data.subdata(in: (data.startIndex+6)..<(data.startIndex+8))
            .withUnsafeBytes { $0.load(as: Int16.self) }.bigEndian
        let checksum = data.subdata(in: (data.startIndex+8)..<(data.startIndex+12))
            .withUnsafeBytes { $0.load(as: UInt32.self) }.bigEndian

        return FrameHeader(
            version: version,
            flags: flags,
            payloadType: payloadType,
            payloadLength: payloadLength,
            extensionLength: extensionLength,
            checksum: checksum
        )
    }

    /// Compute CRC32 checksum for integrity verification
    private func computeChecksum(_ data: Data) -> UInt32 {
        var crc: UInt32 = 0xFFFFFFFF
        for byte in data {
            crc ^= UInt32(byte)
            for _ in 0..<8 {
                crc = (crc >> 1) ^ (0xEDB88320 & (0 &- (crc & 1)))
            }
        }
        return crc ^ 0xFFFFFFFF
    }

    /// Extract payload with extensions from a validated frame
    /// The extensionLength field is signed: negative values indicate
    /// "use protocol-default extensions" (0 bytes of inline extension data)
    func extractPayload(from frameData: Data, header: FrameHeader) -> Data? {
        let headerSize = 12

        // Validate checksum over header (excluding checksum field itself)
        let headerForChecksum = frameData.subdata(in: 0..<8)
        let computed = computeChecksum(headerForChecksum)
        guard computed == header.checksum else { return nil }

        // Calculate total data region to extract
        // extensionLength < 0 means no inline extensions (use defaults)
        let effectiveExtLength: Int
        if header.extensionLength < 0 {
            effectiveExtLength = 0
        } else {
            effectiveExtLength = Int(header.extensionLength)
        }

        let totalLength = Int(header.payloadLength) + effectiveExtLength

        // Bounds check: ensure we don't read past the frame
        guard headerSize + totalLength <= frameData.count else { return nil }

        // Extract the payload region
        let payloadStart = headerSize + effectiveExtLength
        let payloadEnd = payloadStart + Int(header.payloadLength)

        guard payloadEnd <= frameData.count else { return nil }

        return frameData.subdata(in: payloadStart..<payloadEnd)
    }

    /// Process an encrypted frame, decrypt and return plaintext
    func processFrame(_ rawData: Data) -> Data? {
        guard let header = parseHeader(from: rawData) else { return nil }

        // Validate payload type
        guard header.payloadType == 0x0001 || header.payloadType == 0x0002 else {
            return nil
        }

        guard let payload = extractPayload(from: rawData, header: header) else {
            return nil
        }

        // For encrypted frames (type 0x0002), decrypt
        if header.payloadType == 0x0002 {
            return decryptPayload(payload)
        }

        return payload
    }

    /// Decrypt AES-GCM encrypted payload
    private func decryptPayload(_ encrypted: Data) -> Data? {
        // Minimum: 12 byte nonce + 16 byte tag
        guard encrypted.count >= 28 else { return nil }

        let nonce = encrypted.prefix(12)
        let ciphertext = encrypted.dropFirst(12)

        do {
            let sealedBox = try AES.GCM.SealedBox(
                nonce: AES.GCM.Nonce(data: nonce),
                ciphertext: ciphertext.dropLast(16),
                tag: ciphertext.suffix(16)
            )
            return try AES.GCM.open(sealedBox, using: symmetricKey)
        } catch {
            return nil
        }
    }

    /// Batch process multiple frames from a stream buffer
    func processBatch(_ streamData: Data) -> [Data] {
        var results: [Data] = []
        var offset = 0

        while offset < streamData.count {
            guard streamData.count - offset >= 12 else { break }

            let remaining = streamData.subdata(in: offset..<streamData.count)
            guard let header = parseHeader(from: remaining) else { break }

            // Calculate frame size using UNSIGNED effective extension length
            // This ensures negative extensionLength values don't shrink the frame size
            let effectiveExtLength: Int
            if header.extensionLength < 0 {
                effectiveExtLength = 0
            } else {
                effectiveExtLength = Int(header.extensionLength)
            }

            let frameSize = 12 + Int(header.payloadLength) + effectiveExtLength

            guard frameSize > 0 && offset + frameSize <= streamData.count else { break }

            let frameData = streamData.subdata(in: offset..<(offset + frameSize))

            if let result = processFrame(frameData) {
                results.append(result)
            }

            offset += frameSize
        }

        return results
    }
}

// Service endpoint handler
class FrameService {
    private let processor: SecureFrameProcessor

    init() {
        // In production, key comes from vault/KMS
        let keyData = Data((0..<32).map { _ in UInt8.random(in: 0...255) })
        self.processor = SecureFrameProcessor(keyMaterial: keyData)
    }

    func handleIncomingStream(_ data: Data) -> [Data] {
        return processor.processBatch(data)
    }
}
